def nav_html(active: str | None) -> str:
    parts: list[str] = []
    for href, label in NAV:
        cur = ' aria-current="page"' if active == href else ""
        parts.append(f'<li><a class="link" href="{href}"{cur}>{label}</a></li>')
    cur_cta = ' aria-current="page"' if active == '/contact/' else ''
    parts.append(f'<li><a class="btn" href="/contact/"{cur_cta}>Request Truckload Pricing</a></li>')
    return "".join(parts)

def render(page: dict) -> str:
    title = page["title"]
    desc = page["desc"]
    canon = page.get("canonical")  # None = omit (404 soft-index hygiene)
    active = page["active"]
    main = page["main"]
    canon_link = f'<link rel="canonical" href="{canon}">\n' if canon else ""
    og_url = f'<meta property="og:url" content="{canon}">' if canon else ""
    return (
        "<!doctype html>\n"
        "<html lang=\"en\">\n"
        "<head>\n"
        "<meta charset=\"utf-8\">\n"
        '<meta name="viewport" content="width=device-width,initial-scale=1">\n'
        f"<title>{title}</title>\n"
        f'<meta name="description" content="{desc}">\n'
        + canon_link
        + (f'<meta name="robots" content="{page["robots"]}">\n' if page.get("robots") else "")
        + '<!-- Search verification: prefer DNS TXT on b2bstrut.com (see docs). Optional HTML tokens:\n'
        '     <meta name="google-site-verification" content="PASTE_GSC_TOKEN">\n'
        '     <meta name="msvalidate.01" content="PASTE_BING_TOKEN"> -->\n'
        '<meta name="theme-color" content="#14191f">\n'
        f'<meta property="og:type" content="website"><meta property="og:site_name" content="BTB Strut Systems"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}">{og_url}<meta property="og:image" content="https://b2bstrut.com/og-image.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">\n'
        f'<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{title}"><meta name="twitter:description" content="{desc}"><meta name="twitter:image" content="https://b2bstrut.com/og-image.png">\n'
        '<link rel="icon" href="/favicon.svg" type="image/svg+xml">\n'
        '<link rel="preload" href="/fonts/source-sans-3-400.woff2" as="font" type="font/woff2" crossorigin>\n'
        '<link rel="preload" href="/fonts/space-grotesk-700.woff2" as="font" type="font/woff2" crossorigin>\n'
        '<link rel="stylesheet" href="/styles.css?v=' + STYLES_HASH + '">\n'
        + json_ld_scripts(page)
        + "</head>\n"
        "<body>\n"
        '<a class="skip" href="#main">Skip to content</a>\n'
        '<header class="site-header"><div class="container nav">\n'
        f'<a class="brand" href="/">{LOGO}<span>BTB Strut<small>SYSTEMS</small></span></a>\n'
        '<button class="menu-toggle" aria-expanded="false" aria-controls="menu">Menu</button>\n'
        f'<nav aria-label="Primary"><ul id="menu">{nav_html(active)}</ul></nav>\n'
        "</div></header>\n"
        f"<main id=\"main\">{main}</main>\n"
        + FOOTER.replace("/main.js", f"/main.js?v={MAIN_HASH}")
    )

