OG_IMAGE_PNG_B64 = ''

def write(path: Path, data: str | bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if isinstance(data, bytes):
        path.write_bytes(data)
    else:
        path.write_text(data, encoding="utf-8", newline="\n")

def main() -> None:
    PUBLIC.mkdir(parents=True, exist_ok=True)
    for page in PAGES:
        write(PUBLIC / page["path"], render(page))
    write(PUBLIC / "styles.css", STYLES_CSS)
    write(PUBLIC / "main.js", MAIN_JS)
    write(PUBLIC / "robots.txt", ROBOTS_TXT)
    write(PUBLIC / "sitemap.xml", SITEMAP_XML)
    write(PUBLIC / "favicon.svg", FAVICON_SVG)
    write(PUBLIC / "og-image.png", base64.b64decode(OG_IMAGE_PNG_B64))
    fonts_dst = PUBLIC / "fonts"
    fonts_dst.mkdir(parents=True, exist_ok=True)
    # Only ship weights referenced in CSS (400+700 Source Sans 3, 700 Space Grotesk).
    used_fonts = (
        "source-sans-3-400.woff2",
        "source-sans-3-700.woff2",
        "space-grotesk-700.woff2",
    )
    for name in used_fonts:
        src = FONTS_SRC / name
        if src.exists():
            shutil.copy2(src, fonts_dst / name)
    images_dst = PUBLIC / "images"
    images_dst.mkdir(parents=True, exist_ok=True)
    for pattern in ("*.png", "*.webp", "*.avif", "*.jpg", "*.jpeg"):
        for img in sorted(IMAGES_SRC.glob(pattern)):
            shutil.copy2(img, images_dst / img.name)
    print(f"Wrote {len(PAGES)} HTML pages + assets -> {PUBLIC}")

if __name__ == "__main__":
    main()
